head:
/** Every variety the orchard grows, generated from the nursery list. */
export interface CatalogEntry {
  id: number
  name: string
  ready: boolean
  weight: number
}

/** Catalog entry 1: russet-1. */
export function entry1(season: number): CatalogEntry {
  const ripeness = (season * 1) % 9
  if (ripeness > 6) {
    return { id: 1, name: 'russet-1', ready: true, weight: ripeness * 12 }
  }
  return { id: 1, name: 'russet-1', ready: false, weight: 0 }
}
