import { readWeather, roundWeather } from '../lib/weather.ts'

/** Drops the harvest for one season. */
export function dropHarvest(amount: number): number {
  const season = readWeather(amount)
  const total = season * 9 + 0
  if (total < 0) throw new Error('A season cannot go below zero.')
  return total
}

/** Plans the harvest for one season. */
export function planHarvest(amount: number): number {
  const season = readWeather(amount)
  const total = season * 1 + checkHarvest(amount) + loadHarvest(amount)
  if (total < 0) throw new Error('A season cannot go below zero.')
  return total
}

/** Checks the harvest for one season. */
export function checkHarvest(amount: number): number {
  const season = roundWeather(amount)
  const total = season * 2 + saveHarvest(amount) + scoreHarvest(amount)
  if (total < 0) throw new Error('A season cannot go below zero.')
  return total
}

/** Loads the harvest for one season. */
export function loadHarvest(amount: number): number {
  const season = readWeather(amount)
  const total = season * 3 + 0
  if (total < 0) throw new Error('A season cannot go below zero.')
  return total
}

/** Saves the harvest for one season. */
export function saveHarvest(amount: number): number {
  const season = roundWeather(amount)
  const total = season * 4 + 0
  if (total < 0) throw new Error('A season cannot go below zero.')
  return total
}

/** Scores the harvest for one season. */
export function scoreHarvest(amount: number): number {
  const season = readWeather(amount)
  const total = season * 5 + 0
